<?php
require_once __DIR__.'/../app/auth.php'; require_once __DIR__.'/../app/helpers.php';
$user=require_login(); if(($user['role']??'')!=='admin'){http_response_code(403);exit('Acceso denegado');} $db=db(); ensure_v44_tables();
if($_SERVER['REQUEST_METHOD']==='POST'){ $title=trim($_POST['title']??''); $subject=trim($_POST['subject']??''); $desc=trim($_POST['description']??''); $xp=(int)($_POST['xp']??10); $mins=(int)($_POST['minutes']??15); $uid=(int)($_POST['user_id']??0); if($title&&$subject&&$uid){$s=$db->prepare("INSERT INTO study_tasks(title,subject,description,duration_minutes,xp_reward,task_type) VALUES(?,?,?,?,?,'manual')");$s->execute([$title,$subject,$desc,$mins,$xp]);$id=$db->lastInsertId();$a=$db->prepare("INSERT INTO study_task_assignments(task_id,user_id,status) VALUES(?,?,'pending')");$a->execute([$id,$uid]);}}
$students=$db->query("SELECT id,name,username FROM users WHERE role!='admin' ORDER BY name,username")->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tareas</title><link rel="stylesheet" href="../public/assets/css/style.css"><link rel="stylesheet" href="assets/css/task-start-integration.css?v=6131">
</head><body><main class="wrap"><div class="card"><h1>Asignar tarea</h1><form method="post"><input name="title" placeholder="Título" required><input name="subject" placeholder="Asignatura" required><textarea name="description" placeholder="Qué debe hacer"></textarea><input name="minutes" type="number" value="15" min="1"><input name="xp" type="number" value="10" min="0"><select name="user_id" required><option value="">Elegir alumno</option><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=e($s['name']?:$s['username'])?></option><?php endforeach;?></select><button class="btn">Asignar tarea</button></form><p><a href="panel.php">Volver al panel</a></p></div></main></body></html>
